import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [viewStudents, setViewStudents] = useState(false);
  const [viewSupervisors, setViewSupervisors] = useState(false);
  const [viewEvaluators, setViewEvaluators] = useState(false);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editingType, setEditingType] = useState("");

  const navigate = useNavigate();

  // Fetch data from backend on component mount
  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const [studentsResponse, supervisorsResponse, evaluatorsResponse] =
          await Promise.all([
            axios.get("http://localhost:5000/api/student"),
            axios.get("http://localhost:5000/api/admin"),
            axios.get("http://localhost:5000/api/evaluator"),
          ]);
        setStudents(studentsResponse.data);
        setSupervisors(supervisorsResponse.data);
        setEvaluators(evaluatorsResponse.data);
        setViewStudents(studentsResponse.data.length > 0);
        setViewSupervisors(supervisorsResponse.data.length > 0);
        setViewEvaluators(evaluatorsResponse.data.length > 0);
      } catch (error) {
        console.error("Error fetching users", error);
      }
    };

    fetchUsers();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newUser = { name, email, role, registrationNumber, password };

    try {
      if (editingIndex !== null) {
        const userId = editingType === "student" 
          ? students[editingIndex]._id 
          : editingType === "supervisor"
          ? supervisors[editingIndex]._id
          : evaluators[editingIndex]._id;

        // PATCH request to update user
        await axios.patch(`http://localhost:5000/api/${editingType}/${userId}`, newUser);
        
        if (editingType === "student") {
          const updated = [...students];
          updated[editingIndex] = newUser;
          setStudents(updated);
        } else if (editingType === "supervisor") {
          const updated = [...supervisors];
          updated[editingIndex] = newUser;
          setSupervisors(updated);
        } else if (editingType === "evaluator") {
          const updated = [...evaluators];
          updated[editingIndex] = newUser;
          setEvaluators(updated);
        }
      } else {
        // POST request to add a new user
        const userData = { ...newUser, role: role.toLowerCase() };
        await axios.post(`http://localhost:5000/api/${role.toLowerCase()}`, userData);

        if (role === "Student") {
          setStudents([...students, newUser]);
          setViewStudents(true);
        } else if (role === "Supervisor") {
          setSupervisors([...supervisors, newUser]);
          setViewSupervisors(true);
        } else if (role === "Evaluator") {
          setEvaluators([...evaluators, newUser]);
          setViewEvaluators(true);
        }
      }

      // Reset form fields
      setName("");
      setEmail("");
      setRole("");
      setRegistrationNumber("");
      setPassword("");
      setEditingIndex(null);
      setEditingType("");
    } catch (error) {
      console.error("Error submitting user data", error);
    }
  };

  const handleEdit = (index, type) => {
    setEditingIndex(index);
    setEditingType(type);
    const user =
      type === "student"
        ? students[index]
        : type === "supervisor"
        ? supervisors[index]
        : evaluators[index];
    setName(user.name);
    setEmail(user.email);
    setRole(user.role);
    setRegistrationNumber(user.registrationNumber || "");
    setPassword(user.password || "");
  };

  const handleResetPassword = (index, type) => {
    const updatedPassword = prompt("Enter new password:");
    if (updatedPassword) {
      if (type === "student") {
        const updated = [...students];
        updated[index].password = updatedPassword;
        setStudents(updated);
        alert("Password reset successfully for student.");
      } else if (type === "supervisor") {
        const updated = [...supervisors];
        updated[index].password = updatedPassword;
        setSupervisors(updated);
        alert("Password reset successfully for supervisor.");
      } else if (type === "evaluator") {
        const updated = [...evaluators];
        updated[index].password = updatedPassword;
        setEvaluators(updated);
        alert("Password reset successfully for evaluator.");
      }
    }
  };

  const handleDelete = async (index, type) => {
    const userId = type === "student"
      ? students[index]._id
      : type === "supervisor"
      ? supervisors[index]._id
      : evaluators[index]._id;

    try {
      await axios.delete(`http://localhost:5000/api/${type}/${userId}`);

      // Remove user from state
      if (type === "student") {
        const updated = [...students];
        updated.splice(index, 1);
        setStudents(updated);
      } else if (type === "supervisor") {
        const updated = [...supervisors];
        updated.splice(index, 1);
        setSupervisors(updated);
      } else if (type === "evaluator") {
        const updated = [...evaluators];
        updated.splice(index, 1);
        setEvaluators(updated);
      }

      alert("User deleted successfully");
    } catch (error) {
      console.error("Error deleting user", error);
      alert("Failed to delete user");
    }
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <p>Add or edit accounts for students, supervisors, and evaluators</p>

          <div className="user-form-container">
            <h2>{editingIndex !== null ? "Edit User" : "Add / Edit User"}</h2>
            <form onSubmit={handleSubmit} className="user-form">
              <label htmlFor="name">Name</label>
              <input
                type="text"
                id="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
              />

              <label htmlFor="email">Email</label>
              <input
                type="email"
                id="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />

              <label htmlFor="password">Password</label>
              <input
                type="password"
                id="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />

              <label htmlFor="role">Role</label>
              <select
                id="role"
                value={role}
                onChange={(e) => setRole(e.target.value)}
                required
              >
                <option value="">Select Role</option>
                <option value="Student">Student</option>
                <option value="Supervisor">Supervisor</option>
                <option value="Evaluator">Evaluator</option>
              </select>

              {role === "Student" && (
                <>
                  <label htmlFor="registrationNumber">Registration Number</label>
                  <input
                    type="text"
                    id="registrationNumber"
                    value={registrationNumber}
                    onChange={(e) => setRegistrationNumber(e.target.value)}
                    required
                  />
                </>
              )}

              <button type="submit" className="submit-btn">
                {editingIndex !== null ? "Update" : "Submit"}
              </button>
            </form>
          </div>

          {/* Student Table */}
          {viewStudents && students.length > 0 && (
            <div className="student-table">
              <h2>Student List</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Registration Number</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((student, index) => (
                    <tr key={index}>
                      <td>{student.name}</td>
                      <td>{student.email}</td>
                      <td>{student.role}</td>
                      <td>{student.registrationNumber}</td>
                      <td>
                        <button onClick={() => handleEdit(index, "student")}>
                          Edit
                        </button>
                        <button
                          onClick={() => handleResetPassword(index, "student")}
                        >
                          Reset Password
                        </button>
                        <button
                          onClick={() => handleDelete(index, "student")}
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Similar tables for Supervisors and Evaluators */}
          {/* Add similar tables and actions for supervisors and evaluators */}
          
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
